function build_market_deck(): array {
    $deck = [];
    $market_cards = [
        'doorkicker' => 6,
        'driver' => 6,
        'sentinel' => 4,
        'mechanic' => 3,
        'scuba' => 3,
        'hacker' => 3,
        'saboteur' => 3,
        'jack' => 1,
        'chameleon' => 1,
        'racoon' => 1,
        'offshore' => 8,
        'orbital' => 5,
        'burn' => 5,
        'paperwork' => 3,
        'burglary' => 3,
        'paradrop' => 5,
        'multitasking' => 2,
        'training' => 3,
        'reinforcements' => 3,
        'swordcane' => 4,
        'bazooka' => 2,
        'ram' => 4,
        'holoprojector' => 2,
        'drone' => 4,
        'hackingdeck' => 2,
        'grapplinghook' => 2,
        'passports' => 4,
        'motorbike' => 4,
        'limousine' => 3,
        'helicopter' => 2,
    ];
    foreach ($market_cards as $id => $count) {
        for ($i = 0; $i < $count; $i++) {
            $deck[] = $id;
        }
    }
    shuffle($deck);
    return $deck;
}

